pub(super) fn analysis__test_quality__normalize_quality_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut anti_patterns: Value;
    let mut config: Value;
    let mut quality_metrics: Value;
    let mut test_patterns: Value;
    let mut test_sources: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    test_patterns = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("test_patterns"), Value::Array(vec![])))? {
            let mut tp = current;
            if !(tp.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_quality__normalize_test_pattern(tp.clone())?);
        }
        Value::Array(collected_values)
    };
    anti_patterns = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("anti_patterns"), Value::Array(vec![])))? {
            let mut ap = current;
            if !(ap.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_quality__normalize_anti_pattern(ap.clone())?);
        }
        Value::Array(collected_values)
    };
    quality_metrics = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(
            &config,
            &json!("quality_metrics"),
            Value::Array(vec![]),
        ))? {
            let mut qm = current;
            if !(qm.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_quality__normalize_quality_metric(
                qm.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    test_sources = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("test_sources"), Value::Array(vec![])))? {
            let mut ts = current;
            if !(ts.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__test_quality__normalize_test_source(ts.clone())?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("test_patterns".into(), test_patterns.clone()),
            ("anti_patterns".into(), anti_patterns.clone()),
            ("quality_metrics".into(), quality_metrics.clone()),
            ("test_sources".into(), test_sources.clone()),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "limits".into(),
                analysis__test_quality__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
            (
                "determinism_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("determinism_available"),
                    json!(false)
                ))),
            ),
            (
                "timeout_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("timeout_available"),
                    json!(false)
                ))),
            ),
            (
                "isolation_available".into(),
                json!(truth(&get(
                    &config,
                    &json!("isolation_available"),
                    json!(false)
                ))),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

